import math
import numpy as np

def r_1(x):
    return 0.5 * x

def R_1(y_orig, y_new):
    return math.isclose(y_orig, y_new, rel_tol=1e-6)

def r_2(x):
    return math.sqrt(x)

def R_2(y_orig, y_new):
    return math.isclose(y_orig, y_new, rel_tol=1e-6)

def r_3(x):
    return x ** 0.25

def R_3(y_orig, y_new):
    return math.isclose(y_orig, y_new, rel_tol=1e-6)
